// audio_clips.h -- GENERATED by tools/build_audio.py. Do not edit.
//
// Every clip the firmware can play: MONO signed 16-bit PCM at
// AUDIO_CLIP_RATE Hz. Regenerate with `python3 tools/build_audio.py`
// after adding a file to SOURCES there; read that script for why the
// rate is what it is (it is the flash-size knob).
#pragma once

#include <stdint.h>

// The rate every clip below is stored at. audio_player.cpp asserts this
// against the I2S driver's own rate: the two MUST agree, or everything
// plays at the wrong pitch and nothing reports it.
constexpr uint32_t AUDIO_CLIP_RATE = 22050u;

// One playable clip. `name` is what /play?src=<name> accepts and what
// /status reports as `audio` while it plays.
struct AudioClip {
  const char *name;
  const int16_t *pcm;   // mono, AUDIO_CLIP_RATE Hz
  unsigned count;       // samples
  uint32_t rate;        // Hz -- always AUDIO_CLIP_RATE
};

// The sample data. One array per clip, each defined in its own
// src/audio_clip_<name>.cpp so that one big file cannot dominate the
// build, and declared here so the table can reference them.
extern const int16_t pcm_clip[91207u];
extern const int16_t pcm_kachao1[51680u];
extern const int16_t pcm_kachao2[59872u];
extern const int16_t pcm_kachao3[53728u];
extern const int16_t pcm_rapido[137696u];
extern const int16_t pcm_ganadora[162272u];
extern const int16_t pcm_velocidad[85113u];

// The table, in the order tools/build_audio.py lists the clips. That
// order is also the order the page shows them in.
extern const AudioClip kAudioClips[];
